<?php declare(strict_types=1); ?>
<?php if (is_array($savedWork ?? null)): ?><section class="admin-task-panel" aria-label="Saved draft"><div><h2>Your saved <?php echo $draftKind === 'order' ? 'order' : 'request'; ?> draft</h2><p>Saved at <?php echo $escape(date('H:i', $savedWork['saved_at'])); ?>. Available in this signed-in session. Saving again replaces this draft.</p></div><div class="admin-inline-action"><a class="admin-button admin-button--secondary" href="<?php echo $escape($draftRoute . '?resume=1'); ?>">Resume draft</a><form method="post" action="<?php echo $escape($draftRoute); ?>"><input type="hidden" name="csrf_token" value="<?php echo $escape($csrf->token()); ?>"><button class="admin-button admin-button--ghost" name="action" value="discard_draft" type="submit">Discard saved draft</button></form></div></section><?php endif; ?>
